
import React, { useState, useEffect } from 'react';
import { auth, db } from '@/firebase';
import { collection, query, where, onSnapshot, deleteDoc, doc, orderBy, limit } from 'firebase/firestore';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { parseSms, ParsedSms } from '@/utils/smsParser';
import { userDataService } from '@/integrations/firebase/services';
import { Loader2, RefreshCw, Smartphone, CheckCircle2, Trash2 } from 'lucide-react';

const SMSDashboard: React.FC = () => {
  const [text, setText] = useState('');
  const [parsed, setParsed] = useState<ParsedSms | null>(null);
  const [pendingSms, setPendingSms] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(null);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      setCurrentUser(user);
      if (user) {
        // Listen for pending SMS from Android
        const q = query(
          collection(db, 'pendingSmsPopups'),
          where('userId', '==', user.uid),
          orderBy('createdAt', 'desc'),
          limit(10)
        );
        
        const unsubSms = onSnapshot(q, (snapshot) => {
          const msgs = snapshot.docs.map(d => ({ id: d.id, ...d.data() }));
          setPendingSms(msgs);
        });
        
        return () => unsubSms();
      }
    });
    return () => unsubscribe();
  }, []);

  const handleParse = () => {
    if (!text.trim()) return;
    const result = parseSms(text);
    setParsed(result);
    if (result.amount > 0) {
      toast.success('تم تحليل الرسالة بنجاح', { description: `${result.amount} ج.م من ${result.sender || 'مجهول'}` });
    } else {
      toast.warning('لم يتم العثور على مبلغ صالح في الرسالة');
    }
  };

  const handleSave = async () => {
    if (!parsed || !currentUser) return;
    
    try {
      setLoading(true);
      await userDataService.saveUserTransaction(currentUser.uid, {
        amount: parsed.amount,
        senderMsisdn: parsed.sender,
        senderName: parsed.senderName,
        reference: parsed.reference,
        type: parsed.type === 'transfer' ? 'send' : 'receive',
        note: `SMS Parsing: ${parsed.type}`,
        originalSms: parsed.originalText,
        createdAt: new Date().toISOString(),
        status: 'completed'
      });
      
      toast.success('تم تسجيل المعاملة بنجاح');
      setText('');
      setParsed(null);
    } catch (error: any) {
      console.error('Save error:', error);
      toast.error('فشل حفظ المعاملة: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handlePendingSelect = (msg: any) => {
    setText(msg.body || msg.text || '');
    // Auto parse
    const result = parseSms(msg.body || msg.text || '');
    setParsed(result);
  };

  const handleDeletePending = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm('هل أنت متأكد من حذف هذه الرسالة؟')) return;
    try {
      await deleteDoc(doc(db, 'pendingSmsPopups', id));
      toast.success('تم الحذف');
    } catch (e) {
      toast.error('فشل الحذف');
    }
  };

  if (!currentUser) {
    return <div className="p-8 text-center">جاري التحميل...</div>;
  }

  return (
    <div className="space-y-6">
      {/* Pending SMS Section */}
      {pendingSms.length > 0 && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-lg flex items-center gap-2">
              <Smartphone className="h-5 w-5 text-blue-500" />
              رسائل واردة من الهاتف ({pendingSms.length})
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2 max-h-60 overflow-y-auto">
            {pendingSms.map((msg) => (
              <div 
                key={msg.id} 
                className="p-3 border rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer transition-colors flex justify-between items-start group"
                onClick={() => handlePendingSelect(msg)}
              >
                <div className="text-sm">
                  <div className="font-semibold mb-1">{msg.sender || 'مجهول'}</div>
                  <div className="text-muted-foreground line-clamp-2">{msg.body || msg.text}</div>
                  <div className="text-xs text-muted-foreground mt-1 opacity-70">
                    {msg.createdAt?.toDate ? msg.createdAt.toDate().toLocaleString('ar-EG') : 'الآن'}
                  </div>
                </div>
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="h-6 w-6 text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                  onClick={(e) => handleDeletePending(msg.id, e)}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      {/* Manual Entry & Processing */}
      <Card>
        <CardHeader>
          <CardTitle>معالجة الرسائل</CardTitle>
          <CardDescription>الصق نص الرسالة هنا لاستخراج البيانات وتسجيلها</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <Textarea 
            placeholder="مثال: تم استلام مبلغ 1000 جنيه من رقم..." 
            className="min-h-[100px]"
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          
          <div className="flex justify-end">
            <Button onClick={handleParse} disabled={!text.trim()}>
              <RefreshCw className="mr-2 h-4 w-4" />
              تحليل النص
            </Button>
          </div>

          {parsed && (
            <div className="mt-6 p-4 bg-slate-50 dark:bg-slate-900 rounded-lg border border-slate-200 dark:border-slate-800 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-xs text-muted-foreground">المبلغ</Label>
                  <div className="text-xl font-bold text-green-600">{parsed.amount} ج.م</div>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">النوع</Label>
                  <div>
                    {parsed.type === 'transfer' ? (
                      <Badge variant="outline" className="bg-orange-100 text-orange-800 border-orange-200">تحويل (صادر)</Badge>
                    ) : (
                      <Badge variant="outline" className="bg-green-100 text-green-800 border-green-200">استلام (وارد)</Badge>
                    )}
                  </div>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">المرسل / المستلم</Label>
                  <div className="font-mono dir-ltr text-right">{parsed.sender || '-'}</div>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">الاسم</Label>
                  <div>{parsed.senderName || '-'}</div>
                </div>
                {parsed.reference && (
                  <div className="col-span-2">
                    <Label className="text-xs text-muted-foreground">المرجع (Reference)</Label>
                    <div className="font-mono text-xs">{parsed.reference}</div>
                  </div>
                )}
              </div>
            </div>
          )}
        </CardContent>
        <CardFooter className="justify-between border-t p-4 bg-slate-50/50 dark:bg-slate-900/50">
          <Button variant="ghost" onClick={() => { setText(''); setParsed(null); }}>مسح</Button>
          <Button 
            onClick={handleSave} 
            disabled={!parsed || parsed.amount <= 0 || loading}
            className="bg-green-600 hover:bg-green-700 text-white"
          >
            {loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle2 className="mr-2 h-4 w-4" />}
            تأكيد وتسجيل
          </Button>
        </CardFooter>
      </Card>
    </div>
  );
};

export default SMSDashboard;
