import React, { useState } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { useFirebaseAuth } from "@/contexts/FirebaseAuthContext";
import { functions, db } from "@/firebase";
import { httpsCallable } from "firebase/functions";
import { BranchRequestDialog } from "@/components/BranchRequestDialog";
import { collection, query, where, getCountFromServer } from "firebase/firestore";

export default function CPanelPage() {
  const { user, profile, isSubscriptionActive, userSubscription } = useFirebaseAuth();
  const [open, setOpen] = useState(false);
  const [requestOpen, setRequestOpen] = useState(false);
  const [shopName, setShopName] = useState("");
  const [managerName, setManagerName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  const [shopsCount, setShopsCount] = useState(0);

  const isBranchPackageActive = userSubscription?.branchPackage?.status === "active";
  const branchLimit = userSubscription?.branchPackage?.limit || 0;
  
  // Fetch shops count
  React.useEffect(() => {
    if (user) {
      const fetchCount = async () => {
        try {
          const q = query(collection(db, "shops"), where("ownerId", "==", user.uid));
          const snapshot = await getCountFromServer(q);
          setShopsCount(snapshot.data().count);
        } catch (e) {
          console.error("Error fetching shops count:", e);
        }
      };
      fetchCount();
    }
  }, [user]);

  const canManage = (
    profile?.role === "admin" ||
    profile?.role === "merchant" ||
    isSubscriptionActive ||
    (isBranchPackageActive && shopsCount < branchLimit) ||
    true // Keeping existing logic for modal opening, but validation happens in handleCreate
  );

  const resetForm = () => {
    setShopName("");
    setManagerName("");
    setEmail("");
    setPassword("");
  };

  const handleCreate = async () => {
    setMessage(null);
    
    // Clean inputs
    const cleanShopName = shopName.trim();
    const cleanManagerName = managerName.trim();
    const cleanEmail = email.trim();
    const cleanPassword = password;

    // Check branch limit for package holders
    if (isBranchPackageActive && shopsCount >= branchLimit && profile?.role !== "admin" && profile?.role !== "merchant") {
        setMessage(`عذراً، لقد تجاوزت الحد المسموح به من الفروع (${branchLimit}). يرجى ترقية الباقة.`);
        return;
    }

    if (!cleanShopName || !cleanManagerName || !cleanEmail || !cleanPassword) {
      setMessage("يرجى ملء جميع الحقول المطلوبة.");
      return;
    }

    try {
      setLoading(true);

      // 2. Create Shop
      const createFn = httpsCallable(functions, "createShopAndManager");
      const result: any = await createFn({
        shopName: cleanShopName,
        managerName: cleanManagerName,
        email: cleanEmail,
        password: cleanPassword,
        branchCode: null,
      });
      const data = result?.data;

      if (data?.success) {
        // Code is marked as used by backend now.
        setMessage(`تم إنشاء المتجر (${data.shopId}) بنجاح وتفعيل الفرع.`);
        resetForm();
        setOpen(false);
      } else {
        setMessage("فشل إنشاء الحساب، حاول مرة أخرى.");
      }
    } catch (err: any) {
      const msg = err?.message || "حدث خطأ غير متوقع أثناء الإنشاء";
      setMessage(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mx-auto p-4">
      <Card>
        <CardHeader>
          <CardTitle>لوحة التحكم (CPanel)</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-muted-foreground">
                إضافة محل جديد مع إنشاء حساب المدير ليتسجل من صفحة الدخول العادية.
              </p>
            </div>
            <div className="flex gap-2">
                {!isBranchPackageActive && userSubscription?.branchPackage?.status !== 'pending' && (
                     <Button onClick={() => setRequestOpen(true)} variant="outline">
                       طلب إدارة فروع
                     </Button>
                )}
                {userSubscription?.branchPackage?.status === 'pending' && (
                     <Button disabled variant="outline" className="text-yellow-600 border-yellow-200 bg-yellow-50">
                       الطلب قيد المراجعة
                     </Button>
                )}
                <Button onClick={() => setOpen(true)} disabled={!canManage}>
                  إضافة محل
                </Button>
            </div>
          </div>

          {!user && (
            <p className="mt-3 text-sm text-red-600">
              يجب تسجيل الدخول للوصول إلى لوحة التحكم.
            </p>
          )}
          {isBranchPackageActive && (
            <p className="mt-3 text-sm text-green-600 font-medium">
                باقة الفروع مفعلة: لديك {shopsCount} من أصل {branchLimit} فرع.
            </p>
          )}
          {user && !canManage && !isBranchPackageActive && (
            <p className="mt-3 text-sm text-red-600">
              حسابك ليس لديه صلاحيات كافية أو اشتراك/باقة فروع مفعّلة لإنشاء المحلات.
              إذا كنت مشتركًا بباقة مدفوعة أو لديك باقة فروع مفعّلة، ستتمكن من إضافة الحسابات مباشرة.
            </p>
          )}
        </CardContent>
      </Card>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>إضافة محل ومدير</DialogTitle>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="grid gap-2">
              <Label htmlFor="shopName">اسم المحل</Label>
              <Input
                id="shopName"
                value={shopName}
                onChange={(e) => setShopName(e.target.value)}
                placeholder="مثال: متجر أحمد"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="managerName">اسم المدير</Label>
              <Input
                id="managerName"
                value={managerName}
                onChange={(e) => setManagerName(e.target.value)}
                placeholder="مثال: أحمد علي"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="email">الإيميل</Label>
              <Input
                id="email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="example@mail.com"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="password">الباسوورد</Label>
              <Input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    if (canManage) handleCreate();
                  }
                }}
                placeholder="••••••••"
              />
            </div>
            {message && (
              <p className="text-sm text-muted-foreground">{message}</p>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)} disabled={loading}>
              إلغاء
            </Button>
            <Button onClick={handleCreate} disabled={loading || !canManage}>
              {loading ? "جاري الإنشاء..." : "إنشاء الحساب"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <BranchRequestDialog open={requestOpen} onOpenChange={setRequestOpen} />
    </div>
  );
}