const isOfficialVodafoneMessage = (text: string, sender?: string): boolean => {
  try {
    const s = String(sender || '').toLowerCase();
    const t = String(text || '').toLowerCase();
    // Relaxed check for Etisalat / e& money / InstaPay
    if (s.includes('vf-cash') || s.includes('vodafone') || s.includes('vfcash') || s.includes('etisalat') || s.includes('e&')) return true;
    if (/فودافون\s*كاش|etisalat|e&|money/i.test(text)) return true;
    if (t.includes('vodafone cash') || t.includes('etisalat cash')) return true;
    
    // InstaPay specific checks
    // InstaPay messages often come from short codes or banks, or generic senders.
    // If the text contains "Received EGP", we trust it if it has a reference number format.
    if (/Received\s*EGP/i.test(text)) return true;
    
    return false;
  } catch { return false; }
};

const getSelectedWalletMsisdn = async (uid: string): Promise<string> => {
  try {
    const selectedId = String(localStorage.getItem(`selectedWallet_${uid}`) || '').trim();
    if (!selectedId) return '';
    const { merchantWalletService } = await import('@/utils/mobileTransactionHandler');
    const remoteList = await merchantWalletService.getByMerchantId(uid);
    const raw = localStorage.getItem(`wallets_${uid}`);
    const localList = raw ? JSON.parse(raw) : [];
    const all = [...(Array.isArray(localList) ? localList : []), ...(Array.isArray(remoteList) ? remoteList : [])];
    const found = all.find((w: any) => String(w?.id || '') === selectedId);
    const msisdn = String(found?.msisdn || found?.phone || '');
    return msisdn;
  } catch { return ''; }
};

const resolveSelectedWalletId = async (uid: string): Promise<string> => {
  try {
    const keys = Object.keys(localStorage);
    const selPrefix = `selectedWallet_${uid}`;
    const walletsPrefix = `wallets_${uid}`;
    const selectedKey = keys.find(k => k.startsWith(selPrefix));
    if (selectedKey) {
      const v = localStorage.getItem(selectedKey) || '';
      if (v) return v;
    }
    const { merchantWalletService } = await import('@/utils/mobileTransactionHandler');
    const remoteList = await merchantWalletService.getByMerchantId(uid);
    const raw = localStorage.getItem(walletsPrefix);
    const localList = raw ? JSON.parse(raw) : [];
    const all = [...(Array.isArray(localList) ? localList : []), ...(Array.isArray(remoteList) ? remoteList : [])];
    if (all.length > 0) {
      const def = all.find((w: any) => !!w?.isDefault);
      const id = String((def?.id ?? all[0]?.id) || '').trim();
      if (id) return id;
    }
  } catch {}
  return '';
};

