    let startY = 0;
    let activeTarget: EventTarget | null = null;
    const onTouchStart = (e: TouchEvent) => {
      startY = e.touches?.[0]?.clientY || 0;
      activeTarget = e.target;
    };
    const onTouchMove = (e: TouchEvent) => {
      const currentY = e.touches?.[0]?.clientY || 0;
      const scroller = document.scrollingElement || document.documentElement;
      const scrollTop = scroller.scrollTop || window.scrollY || 0;
      const maxScroll = (scroller.scrollHeight - scroller.clientHeight) || 0;
      // منع السحب للتحديث فقط عند أعلى الصفحة مع سحب لأسفل،
      // وتجنب المنع إذا كان الهدف داخل عنصر قابل للتمرير عموديًا
      const el = (activeTarget as HTMLElement) || null;
      const hasScrollableAncestor = (() => {
        let node: HTMLElement | null = el;
        while (node && node !== document.body) {
          const style = window.getComputedStyle(node);
          const overflowY = style.overflowY;
          if ((overflowY === 'auto' || overflowY === 'scroll') && node.scrollHeight > node.clientHeight) {
            // إذا كان هناك عنصر قابل للتمرير وفيه مساحة للتمرير، لا نمنع السلوك الافتراضي
            return true;
          }
          node = node.parentElement;
        }
        return false;
      })();

      if (!hasScrollableAncestor && scrollTop <= 0 && currentY > startY) {
        if (e.cancelable) e.preventDefault();
      }

      // منع الارتداد عند أسفل الصفحة مع سحب لأعلى (يظهر إطار أسود/فارغ أسفل المحتوى)
      if (!hasScrollableAncestor && scrollTop >= maxScroll && currentY < startY) {
        if (e.cancelable) e.preventDefault();
      }
    };
    document.addEventListener('touchstart', onTouchStart, { passive: true });
    document.addEventListener('touchmove', onTouchMove, { passive: false });

