const AutoConfirmTimer = ({ enabled, duration, onConfirm, isLocal }: { enabled: boolean, duration: number, onConfirm: () => void, isLocal?: boolean }) => {
  const [timeLeft, setTimeLeft] = React.useState(duration);
  const [isPaused, setIsPaused] = React.useState(false);
  const onConfirmRef = React.useRef(onConfirm);
  const endTimeRef = React.useRef<number | null>(null);

  React.useEffect(() => { onConfirmRef.current = onConfirm; }, [onConfirm]);

  React.useEffect(() => {
    if (enabled) { 
        setTimeLeft(duration); 
        setIsPaused(false);
        endTimeRef.current = Date.now() + duration * 1000;
    }
  }, [enabled, duration]);

  React.useEffect(() => {
    if (!enabled || isPaused) {
        // When paused, we clear the target end time
        // If unpaused later, we would need to recalculate based on remaining time
        // But for simplicity in this specific UI, pause just stops visual updates
        endTimeRef.current = null;
        return;
    }
    // if (isLocal === false) return; // Allow remote timer

    if (endTimeRef.current === null) {
        endTimeRef.current = Date.now() + timeLeft * 1000;
    }

    const timer = setInterval(() => {
      const now = Date.now();
      const end = endTimeRef.current || (now + 1000);
      const remaining = Math.max(0, (end - now) / 1000);
      
      setTimeLeft(remaining);

      if (remaining <= 0) {
        clearInterval(timer);
        onConfirmRef.current();
      }
    }, 100);

    return () => clearInterval(timer);
  }, [enabled, isPaused, isLocal]);

  if (!enabled) return null;
  // if (isLocal === false) return null; // Allow remote timer

  const progress = Math.min(100, Math.max(0, (timeLeft / duration) * 100));

  return (
    <div className="mb-4 relative overflow-hidden rounded-xl bg-emerald-50 border border-emerald-100 p-3 shadow-inner">
      <div className="flex items-center justify-between relative z-10">
        <div className="flex items-center gap-2 text-emerald-900 font-bold text-sm">
           <div className="relative w-5 h-5 flex items-center justify-center">
             <svg className="animate-spin text-emerald-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
               <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
               <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
             </svg>
           </div>
           <span>تسجيل تلقائي خلال {Math.ceil(timeLeft)} ثانية</span>
        </div>
        <button 
          onClick={() => setIsPaused(true)}
          className="text-xs font-bold text-white bg-emerald-500 hover:bg-emerald-600 px-3 py-1.5 rounded-lg shadow-sm transition-all active:scale-95"
        >
          إيقاف
        </button>
      </div>
      {/* Progress Bar */}
      <div className="absolute bottom-0 left-0 h-1 bg-emerald-200 w-full" />
      <div 
        className="absolute bottom-0 left-0 h-1 bg-emerald-600 transition-all duration-100 ease-linear" 
        style={{ width: `${progress}%` }}
      />
    </div>
  );
};

