const NativeHome: React.FC = () => {
  const { user, loading } = useFirebaseAuth();
  const [showLoader, setShowLoader] = useState<boolean>(true);
  const navigate = useNavigate();

  useEffect(() => {
    const hardOpen = setTimeout(() => setShowLoader(false), 7000);
    return () => clearTimeout(hardOpen);
  }, []);

  useEffect(() => {
    const handleSplash = async () => {
      if (Capacitor.isNativePlatform() && Capacitor.getPlatform() === 'android') {
        if (!loading) {
          // Add a small delay to ensure the UI is painted
          setTimeout(async () => {
            try { await SplashScreen.hide(); } catch (e) { console.warn('Error hiding splash:', e); }
          }, 100);
        } else {
          // Safety timeout: if auth takes too long (>8s), hide splash to show loader
          const timer = setTimeout(async () => {
             try { await SplashScreen.hide(); } catch {}
          }, 8000);
          return () => clearTimeout(timer);
        }
      }
    };
    handleSplash();
  }, [loading]);

  useEffect(() => {
    if (loading) {
      setShowLoader(true);
    } else {
      try { window.dispatchEvent(new CustomEvent('loader:finish')); } catch {}
      const onDone = () => setShowLoader(false);
      try { window.addEventListener('loader:progress-done', onDone); } catch {}
      const safety = setTimeout(() => setShowLoader(false), 1500);
      return () => { try { window.removeEventListener('loader:progress-done', onDone); } catch {} ; clearTimeout(safety); };
    }
  }, [loading]);

  useEffect(() => {
    if (!showLoader && !loading && !user) {
      try { navigate('/user/login'); } catch {}
    }
  }, [showLoader, loading, user]);

  if (showLoader) return <LogoLoader />;
  return user ? <ProtectedUserDashboard /> : <UserLoginPage />;
};

