import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { 
  Home, 
  FileText, 
  Plus, 
  BarChart3, 
  Settings,
  ArrowDown,
  Receipt,
  ArrowUpDown,
  X,
  TrendingUp,
  LogOut,
  MessageCircle,
  CreditCard,
  Share2,
  Clock,
  Wrench,
  AlertTriangle,
  BadgePercent,
  Store,
  Phone,
  Smartphone,
  Landmark
} from 'lucide-react';
import { useFirebaseAuth } from '@/contexts/FirebaseAuthContext';
import { useToast } from '@/hooks/use-toast';
import { SubscriptionPlan } from '@/utils/subscriptionService';
import { Capacitor } from '@capacitor/core';
import FawryMachineIcon from '@/components/icons/FawryMachineIcon';

interface NavItem {
  id: string;
  label: string;
  icon: React.ComponentType<any>;
  path: string;
  isSpecial?: boolean;
  action?: () => void;
}

interface QuickAction {
  id: string;
  label: string;
  icon: React.ComponentType<any>;
  action: () => void;
  color: string;
}

const getHiddenQuickActions = (uid?: string | null): string[] => {
  try {
    const key = uid || 'default';
    const raw = localStorage.getItem(`hiddenQuickActions_${key}`) ?? localStorage.getItem('hiddenQuickActions');
    const parsed = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((x: any) => typeof x === 'string');
  } catch {
    return [];
  }
};

const MobileBottomNavigation: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { signOut, user, userSubscription } = useFirebaseAuth();
  const { toast } = useToast();
  const [isQuickMenuOpen, setIsQuickMenuOpen] = useState(false);
  const [isSettingsMenuOpen, setIsSettingsMenuOpen] = useState(false);
  const [hiddenQuickActions, setHiddenQuickActions] = useState<string[]>(() => getHiddenQuickActions(user?.uid));
  const [unreadSupportCount, setUnreadSupportCount] = useState(0);

  React.useEffect(() => {
    const handleUnreadUpdate = (e: CustomEvent) => {
      setUnreadSupportCount(e.detail.count);
    };
    window.addEventListener('support-chat-unread', handleUnreadUpdate as EventListener);
    
    // Initial load
    const savedCount = localStorage.getItem('support_chat_unread_count');
    if (savedCount) setUnreadSupportCount(parseInt(savedCount, 10));

    return () => window.removeEventListener('support-chat-unread', handleUnreadUpdate as EventListener);
  }, []);

  React.useEffect(() => {
    setHiddenQuickActions(getHiddenQuickActions(user?.uid));
  }, [user?.uid]);

  const handleDashboardAction = (actionName: string, stateKey: string | null, extraState: any = {}, extraPayload: any = {}) => {
    if (location.pathname.startsWith('/user/dashboard')) {
      window.dispatchEvent(new CustomEvent('dashboard-navigation-action', {
        detail: {
          action: actionName,
          payload: extraPayload
        }
      }));
    } else {
      const state = stateKey ? { [stateKey]: true, ...extraState } : { ...extraState };
      navigate('/user/dashboard', { state });
    }
  };

  const navItems: NavItem[] = [
    {
      id: 'home',
      label: 'الرئيسية',
      icon: Home,
      path: '/user/dashboard',
      action: () => {
        const scrollToTop = () => {
          // 1. Try the specific ID
          const dashboardElement = document.getElementById('dashboard-content-container');
          if (dashboardElement) {
            dashboardElement.scrollTop = 0;
            dashboardElement.scrollTo(0, 0);
          }
          
          // 2. Try the class name (fallback)
          const dashboardByClass = document.querySelector('.user-dashboard');
          if (dashboardByClass) {
            dashboardByClass.scrollTop = 0;
            dashboardByClass.scrollTo(0, 0);
          }

          // 3. Try global window/body (fallback)
          window.scrollTo(0, 0);
          document.body.scrollTop = 0;
          document.documentElement.scrollTop = 0;
        };

        if (location.pathname === '/user/dashboard') {
          // Clear any state if we are just "going home"
          if (location.state && Object.keys(location.state).length > 0) {
             navigate('/user/dashboard', { replace: true, state: {} });
          }
          scrollToTop();
        } else {
          navigate('/user/dashboard');
        }

        // Aggressive retry strategy
        setTimeout(scrollToTop, 10);
        setTimeout(scrollToTop, 50);
        setTimeout(scrollToTop, 150);
        setTimeout(scrollToTop, 300);
      }
    },
    {
      id: 'debts',
      label: 'الديون',
      icon: FileText,
      path: '/debts',
      action: () => {
        if (location.state?.openDebtDialog) return;
        handleDashboardAction('debts', 'openDebtDialog');
      }
    },
    {
      id: 'transfer',
      label: 'تحويل',
      icon: ArrowUpDown,
      path: '/transfer',
      action: () => {
        // Always force update even if already on the section, to ensure reset
        handleDashboardAction(
          'transaction-section', 
          'openTransactionSection', 
          { transactionType: 'transfer', startNewTransaction: true }, 
          { transactionType: 'transfer', startNewTransaction: true, skipAnimation: true }
        );
      }
    },
    {
      id: 'add',
      label: '',
      icon: Plus,
      path: '/add',
      isSpecial: true
    },
    {
      id: 'withdraw',
      label: 'سحب',
      icon: ArrowDown,
      path: '/withdraw',
      action: () => {
        // Always force update to ensure reset and instant jump
        handleDashboardAction(
          'transaction-section', 
          'openTransactionSection', 
          { transactionType: 'withdraw', startNewTransaction: true }, 
          { transactionType: 'withdraw', startNewTransaction: true, skipAnimation: true }
        );
      }
    },
    {
      id: 'support',
      label: 'الدعم',
      icon: MessageCircle,
      path: '#',
      action: () => {
        // Dispatch event to open the chat widget
        window.dispatchEvent(new CustomEvent('open-support-chat'));
      }
    },
    {
      id: 'settings',
      label: 'الإعدادات',
      icon: Settings,
      path: '/user/dashboard',
      action: () => {
        handleDashboardAction('profile-settings', 'openProfileSettings');
      }
    }
  ];

  const quickActions: QuickAction[] = [
    {
      id: 'lines',
      label: 'خطوط',
      icon: Smartphone,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openSimCardsDialog) return;
        handleDashboardAction('lines', 'openSimCardsDialog');
      },
      color: '#9333ea'
    },
    {
      id: 'installment',
      label: 'التقسيط',
      icon: BadgePercent,
      action: () => {
        setIsQuickMenuOpen(false);
        const plan = userSubscription?.subscription?.planType;
        if (plan === SubscriptionPlan.TAHWEELA || plan === SubscriptionPlan.ZERO) {
          toast({ title: 'غير متوفر لاشتراكك', description: 'إدارة التقسيط غير متاحة في هذه الخطة.', variant: 'destructive' });
          return;
        }
        if (location.state?.openInstallment) return;
        handleDashboardAction('installment', 'openInstallment');
      },
      color: '#7C3AED'
    },
    {
      id: 'maintenance',
      label: 'الصيانة',
      icon: Wrench,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openMaintenanceDialog) return;
        handleDashboardAction('maintenance', 'openMaintenanceDialog');
      },
      color: '#0EA5E9'
    },
    {
      id: 'machine',
      label: 'الماكينة',
      icon: FawryMachineIcon,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openMachineDailyDialog) return;
        handleDashboardAction('machine-daily', 'openMachineDailyDialog');
      },
      color: '#F59E0B'
    },
    {
      id: 'atm-withdraw',
      label: 'سحب ATM',
      icon: Landmark,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openAtmWithdrawDialog) return;
        handleDashboardAction('atm-withdraw', 'openAtmWithdrawDialog');
      },
      color: '#10B981'
    },
    {
      id: 'pending-operations',
      label: 'عمليات معلقة',
      icon: Clock,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openPendingOperationsDialog) return;
        handleDashboardAction('pending-operations', 'openPendingOperationsDialog');
      },
      color: '#ea580c'
    },
    {
      id: 'credit-cards',
      label: 'كروت الائتمان',
      icon: CreditCard,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openCreditCardsDialog) return;
        handleDashboardAction('credit-cards', 'openCreditCardsDialog');
      },
      color: '#8B5CF6'
    },
    {
      id: 'sales',
      label: 'المبيعات',
      icon: TrendingUp,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openSalesDialog) return;
        handleDashboardAction('sales', 'openSalesDialog');
      },
      color: '#F59E0B'
    },
    {
      id: 'shop-expenses',
      label: 'مصروفات المحل',
      icon: Receipt,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openShopExpensesDialog) return;
        handleDashboardAction('shop-expenses', 'openShopExpensesDialog');
      },
      color: '#F97316'
    },
    {
      id: 'deficiencies',
      label: 'النواقص',
      icon: AlertTriangle,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openDeficienciesDialog) return;
        handleDashboardAction('deficiencies', 'openDeficienciesDialog');
      },
      color: '#DB2777'
    },

    {
      id: 'branch-management',
      label: 'إدارة الفروع',
      icon: Store,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openBranchManagement) return;
        handleDashboardAction('branch-management', 'openBranchManagement');
      },
      color: '#14b8a6'
    },
    {
      id: 'my-client-numbers',
      label: 'أرقامي',
      icon: Phone,
      action: () => {
        setIsQuickMenuOpen(false);
        if ((location.state as any)?.openMyClientNumbersDialog) return;
        handleDashboardAction('my-client-numbers', 'openMyClientNumbersDialog');
      },
      color: '#22C55E'
    },
    {
      id: 'add-wallet',
      label: 'إضافة محفظة',
      icon: Plus,
      action: () => {
        setIsQuickMenuOpen(false);
        handleDashboardAction(
          'wallet-management',
          'openWalletManagement',
          { walletManagementMode: 'add' },
          { autoStartAdd: true }
        );
      },
      color: '#EF4444'
    },
    {
      id: 'cashier-shift',
      label: 'وردية الكاشير',
      icon: Clock,
      action: () => {
        setIsQuickMenuOpen(false);
        if (location.state?.openCashierShiftModal) return;
        handleDashboardAction('cashier-shift', 'openCashierShiftModal');
      },
      color: '#3B82F6'
    },
    {
      id: 'logout',
      label: 'تسجيل الخروج',
      icon: LogOut,
      action: async () => {
        setIsQuickMenuOpen(false);
        try {
          await signOut();
        } catch (error) {
          console.error('Logout error:', error);
        }
      },
      color: '#EF4444'
    }
  ];

  // عرض جميع الأوامر السريعة كما في التصميم
  const displayedQuickActions = quickActions.filter(action => !hiddenQuickActions.includes(action.id));

  const settingsActions: QuickAction[] = [
    {
      id: 'shop-expenses-settings',
      label: 'مصروفات المحل',
      icon: Receipt,
      action: () => {
        setIsSettingsMenuOpen(false);
        if (location.state?.openShopExpensesDialog) return;
        navigate('/user/dashboard', {
          state: { openShopExpensesDialog: true }
        });
      },
      color: '#F97316'
    },
    {
      id: 'profile-settings',
      label: 'إعدادات الملف الشخصي',
      icon: Settings,
      action: () => {
        setIsSettingsMenuOpen(false);
        if (location.pathname.startsWith('/user/dashboard')) {
          window.dispatchEvent(new CustomEvent('dashboard-navigation-action', { 
            detail: { action: 'profile-settings' } 
          }));
        } else {
          navigate('/user/dashboard', { 
            state: { openProfileSettings: true } 
          });
        }
      },
      color: '#6366F1'
    },
    {
      id: 'logout',
      label: 'تسجيل الخروج',
      icon: LogOut,
      action: async () => {
        setIsSettingsMenuOpen(false);
        try {
          await signOut();
        } catch (error) {
          console.error('Logout error:', error);
        }
      },
      color: '#EF4444'
    }
  ];

  const handleNavigation = (path: string, isSpecial?: boolean, action?: () => void, id?: string) => {
    const plan = userSubscription?.subscription?.planType;
    const isTahweela = plan === SubscriptionPlan.TAHWEELA;
    const allowPath = (p: string) => {
      const allowed = ['/user/dashboard', '/profile-settings'];
      return allowed.includes(p);
    };
    const allowActionId = (actionId?: string) => {
      return actionId === 'debts' || actionId === 'support';
    };
    if (action) {
      if (isTahweela) {
        if (!allowActionId(id) && !allowPath(path)) {
          toast({ title: 'غير متوفر لاشتراكك', description: 'هذه الميزة غير متاحة في باقة تحويله.' , variant: 'destructive' });
          return;
        }
      }
      action();
    } else if (isSpecial && path === '/add') {
      if (isTahweela) {
        toast({ title: 'غير متوفر لاشتراكك', description: 'القائمة السريعة غير متاحة في باقة تحويله.', variant: 'destructive' });
        return;
      }
      setIsQuickMenuOpen(!isQuickMenuOpen);
    } else if (!isSpecial) {
      if (isTahweela && !allowPath(path)) {
        toast({ title: 'غير متوفر لاشتراكك', description: 'هذه الصفحة غير متاحة في باقة تحويله.', variant: 'destructive' });
        return;
      }
      if (location.pathname === path && !action) {
        return;
      }
      navigate(path);
    }
  };

  const isActive = (path: string) => {
    return location.pathname === path;
  };

  return (
    <div className="mobile-bottom-nav">
      {/* Quick Actions Menu - Floating Buttons */}
      {isQuickMenuOpen && (
        <>
          {/* Overlay */}
          <div 
            className="quick-actions-overlay"
            onClick={() => setIsQuickMenuOpen(false)}
          />
          {/* BottomSheet Grid Actions (Android Style) */}
          <div className="quick-actions-bottomsheet">
            <div className="quick-actions-grid">
              {displayedQuickActions.map((action, index) => (
                <button
                  key={action.id}
                  type="button"
                  className="quick-action-tile"
                  onClick={() => {
                    const plan = userSubscription?.subscription?.planType;
                    if (plan === SubscriptionPlan.TAHWEELA) {
                      toast({ title: 'غير متوفر لاشتراكك', description: 'هذه الميزة غير متاحة في باقة تحويله.', variant: 'destructive' });
                      return;
                    }
                    setIsQuickMenuOpen(false);
                    action.action();
                  }}
                  style={{
                    '--action-color': action.color,
                    '--animation-delay': '0s'
                  } as React.CSSProperties}
                >
                  <div className="quick-action-icon">
                    <action.icon className="action-icon" />
                  </div>
                  <span className="quick-action-label">{action.label}</span>
                </button>
              ))}
            </div>
          </div>
        </>
      )}

      {/* Settings Menu - Floating Buttons */}
      {isSettingsMenuOpen && (
        <>
          {/* Overlay */}
          <div 
            className="quick-actions-overlay"
            onClick={() => setIsSettingsMenuOpen(false)}
          />
          {/* BottomSheet Grid Settings (Android Style) */}
          <div className="quick-actions-bottomsheet">
            <div className="quick-actions-grid">
              {settingsActions.map((action, index) => (
                <button
                  key={action.id}
                  type="button"
                  className="quick-action-tile"
                  onClick={() => {
                    const plan = userSubscription?.subscription?.planType;
                    const allowedIds = new Set(['logout', 'profile-settings']);
                    if (plan === SubscriptionPlan.TAHWEELA && !allowedIds.has(action.id)) {
                      toast({ title: 'غير متوفر لاشتراكك', description: 'هذه الميزة غير متاحة في باقة تحويله.', variant: 'destructive' });
                      return;
                    }
                    setIsSettingsMenuOpen(false);
                    action.action();
                  }}
                  style={{
                    '--action-color': action.color,
                    '--animation-delay': `${index * 0.06}s`
                  } as React.CSSProperties}
                >
                  <div className="quick-action-icon">
                    <action.icon className="action-icon" />
                  </div>
                  <span className="quick-action-label">{action.label}</span>
                </button>
              ))}
            </div>
          </div>
        </>
      )}

      <nav className="mobile-bottom-nav-container">
        {navItems.map((item) => {
          const IconComponent = item.icon;
          const active = isActive(item.path);
          
          return (
            <button
              key={item.id}
              onClick={() => handleNavigation(item.path, item.isSpecial, item.action, item.id)}
              className={`mobile-nav-item ${active ? 'active' : ''} ${item.isSpecial ? 'special' : ''}`}
              type="button"
              aria-label={item.label}
              style={{ backgroundColor: 'transparent' }}
            >
              <div className={`nav-icon-container relative ${item.isSpecial ? 'special-icon' : ''} ${item.isSpecial && item.id === 'add' && isQuickMenuOpen ? 'special-open' : ''}`}>
                <IconComponent 
                  className={`nav-icon ${active ? 'active-icon' : ''} ${item.isSpecial ? 'special-icon-svg' : ''} ${
                    item.isSpecial && item.id === 'settings' && isSettingsMenuOpen ? 'rotated' : ''
                  }`}
                />
                {item.id === 'support' && unreadSupportCount > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white shadow-sm ring-1 ring-white">
                    {unreadSupportCount > 99 ? '99+' : unreadSupportCount}
                  </span>
                )}
              </div>
              {!item.isSpecial && (
                <span className={`nav-label ${active ? 'active-label' : ''}`}>
                  {item.label}
                </span>
              )}
            </button>
          );
        })}
      </nav>
    </div>
  );
};

export default MobileBottomNavigation;
