import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Lock } from 'lucide-react';
import { auth } from '@/firebase';
import { EmailAuthProvider, reauthenticateWithCredential } from 'firebase/auth';
import { useToast } from '@/hooks/use-toast';

interface PasswordConfirmDialogProps {
  open: boolean;
  onOpenChange?: (open: boolean) => void;
  title?: string;
  description?: string;
  onSuccess: () => void;
}

const PasswordConfirmDialog: React.FC<PasswordConfirmDialogProps> = ({
  open,
  onOpenChange,
  title = 'تأكيد كلمة المرور',
  description = 'أدخل كلمة مرور تسجيل الدخول للمتابعة',
  onSuccess,
}) => {
  const { toast } = useToast();
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleConfirm = async () => {
    setError(null);
    try {
      const currentUser = auth.currentUser;
      if (!currentUser || !currentUser.email) {
        setError('لا يوجد مستخدم مسجل حالياً. يرجى تسجيل الدخول أولاً.');
        return;
      }
      setIsLoading(true);
      const credential = EmailAuthProvider.credential(currentUser.email, password);
      await reauthenticateWithCredential(currentUser, credential);
      setIsLoading(false);
      setPassword('');
      toast({ title: 'تم التأكيد', description: 'تم التحقق من كلمة المرور بنجاح' });
      onSuccess();
      if (onOpenChange) onOpenChange(false);
    } catch (e: any) {
      console.error('إعادة التحقق بكلمة المرور فشلت:', e);
      setIsLoading(false);
      const code = e?.code || '';
      if (code === 'auth/wrong-password') {
        setError('كلمة المرور غير صحيحة. حاول مرة أخرى.');
      } else if (code === 'auth/too-many-requests') {
        setError('تمت محاولات كثيرة. يرجى الانتظار قليلاً ثم المحاولة.');
      } else {
        setError('حدث خطأ أثناء التحقق. حاول مرة أخرى.');
      }
    }
  };

  const handleClose = (openVal: boolean) => {
    if (onOpenChange) onOpenChange(openVal);
    if (!openVal) {
      setPassword('');
      setError(null);
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[400px] bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800" dir="rtl">
        <DialogHeader>
          <DialogTitle className="text-right text-gray-900 dark:text-gray-100">{title}</DialogTitle>
          <DialogDescription className="text-right text-gray-500 dark:text-gray-400">{description}</DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-2">
          <div className="grid grid-cols-4 items-center gap-2">
            <label htmlFor="password" className="text-right col-span-1 text-sm text-gray-700 dark:text-gray-300">كلمة المرور</label>
            <div className="col-span-3 relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    handleConfirm();
                  }
                }}
                placeholder="نفس كلمة مرور تسجيل الدخول"
                autoComplete="off"
                className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-900 dark:text-gray-100"
              />
            </div>
          </div>
          {error && (
            <div className="text-red-600 dark:text-red-400 text-xs text-right">{error}</div>
          )}
        </div>
        <DialogFooter className="flex justify-end gap-2">
          <Button
            variant="outline"
            onClick={() => handleClose(false)}
            disabled={isLoading}
            className="dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-800"
          >
            إلغاء
          </Button>
          <Button
            onClick={handleConfirm}
            disabled={isLoading}
            className="bg-emerald-600 hover:bg-emerald-700 text-white"
          >
            {isLoading ? 'جاري التحقق...' : 'تأكيد'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default PasswordConfirmDialog;