import React from 'react';
import { Minus, X, RefreshCcw, Square } from 'lucide-react';
import { listenDesktopUpdates, selectDesktopUrl } from '@/utils/appDownloadService';

/**
 * شريط علوي بسيط يعرض أزرار:
 * - تصغير إلى شريط المهام
 * - إغلاق التطبيق
 *
 * يُعرض أعلى يمين النافذة، ولا يغيّر وضع ملء الشاشة إلا أثناء التصغير.
 */
const TitleBarOverlay: React.FC = () => {
  type ElectronAPI = {
    windowMinimize: () => Promise<unknown>;
    windowClose: () => Promise<unknown>;
    onUpdateAvailable: (cb: (payload: unknown) => void) => void;
    onUpdateDownloaded: (cb: (payload: unknown) => void) => void;
    onUpdateError?: (cb: (payload: any) => void) => void;
    onUpdateProgress?: (cb: (payload: { percent?: number|null; downloaded?: number; total?: number }) => void) => void;
    checkUpdate: () => Promise<unknown>;
    downloadUpdate: () => Promise<unknown>;
    applyUpdate: () => Promise<unknown>;
    windowReload?: () => Promise<unknown>;
    windowFullscreen?: () => Promise<unknown>;
  };
  const electronAPI = (typeof window !== 'undefined' ? (window as unknown as { electronAPI?: ElectronAPI }).electronAPI : undefined);
  const isElectron = !!electronAPI;
  const [updateAvailable, setUpdateAvailable] = React.useState<boolean>(false);
  const [isUpdateDialogOpen, setIsUpdateDialogOpen] = React.useState<boolean>(false);
  const [isDownloadingUpdate, setIsDownloadingUpdate] = React.useState<boolean>(false);
  const [updateProgress, setUpdateProgress] = React.useState<number>(0);
  const [updateUrl, setUpdateUrl] = React.useState<string>('');
  const [isRefreshing, setIsRefreshing] = React.useState<boolean>(false);

  const handleMinimize = async () => {
    try {
      if (isElectron && electronAPI) {
        await electronAPI.windowMinimize();
      } else {
        // للمعاينة أثناء التطوير فقط
        console.info('windowMinimize (dev preview)');
      }
    } catch (e) {
      console.warn('failed to minimize', e);
    }
  };

  const handleClose = async () => {
    // If update is forced and available, do not allow closing (unless it's to quit/install, which windowClose does)
    // But if the user intent is to "exit window and open without update", we rely on ProfileIcon's check on startup.
    
    try {
      if (isElectron && electronAPI) {
        await electronAPI.windowClose();
      } else {
        // للمعاينة أثناء التطوير فقط
        console.info('windowClose (dev preview)');
      }
    } catch (e) {
      console.warn('failed to close', e);
    }
  };

  const handleRefresh = async () => {
    if (isRefreshing) return;
    setIsRefreshing(true);
    try {
      try { window.dispatchEvent(new CustomEvent('app:softRefresh')); } catch {}
      if (isElectron && electronAPI && typeof electronAPI.windowReload === 'function') {
        setTimeout(() => { try { electronAPI.windowReload(); } catch {} }, 50);
        setTimeout(() => setIsRefreshing(false), 600);
        return;
      }
      try { window.location.reload(); } catch {}
    } catch (e) {
      console.warn('failed to soft refresh', e);
      setIsRefreshing(false);
    }
  };

  React.useEffect(() => {
    if (!isElectron || !electronAPI) return;
    try {
      electronAPI.onUpdateAvailable(() => setUpdateAvailable(true));
      electronAPI.onUpdateDownloaded(() => setUpdateAvailable(true));
      if (typeof electronAPI.onUpdateError === 'function') {
        electronAPI.onUpdateError(() => { setIsDownloadingUpdate(false); });
      }
      if (typeof electronAPI.onUpdateProgress === 'function') {
        electronAPI.onUpdateProgress((payload) => {
          const p = (payload?.percent == null ? 0 : Number(payload.percent));
          setIsDownloadingUpdate(true);
          setUpdateProgress(Math.max(0, Math.min(100, isNaN(p) ? 0 : p)));
        });
      }
      electronAPI.checkUpdate();
    } catch (e) { console.warn('update init failed', e); }
  }, [isElectron, electronAPI]);

  React.useEffect(() => {
    const unsub = listenDesktopUpdates((data) => {
      const v = String(data?.version || '');
      if (v) {
        setUpdateAvailable(true);
        const preferred = selectDesktopUrl({ downloadURL_64: data?.downloadURL_64, downloadURL_32: data?.downloadURL_32 }) || '';
        setUpdateUrl(preferred);
      }
    });
    return () => { try { unsub(); } catch {} };
  }, []);

  const handleOpenUpdate = () => {
    setIsUpdateDialogOpen(true);
  };

  const handleConfirmUpdate = async () => {
    try {
      if (electronAPI) {
        try { await electronAPI.checkUpdate(); } catch {}
        setIsUpdateDialogOpen(true);
        setIsDownloadingUpdate(true);
        setUpdateProgress(0);
        const res = await (electronAPI as any).downloadUpdate?.(updateUrl) ?? await electronAPI.downloadUpdate();
        if (typeof res === 'string' && res.startsWith('err:')) {
          setIsDownloadingUpdate(false);
        } else if (res === 'noop') {
          setIsDownloadingUpdate(false);
        } else if (res === 'manual') {
          try { if (updateUrl) window.open(updateUrl, '_blank'); } catch {}
          try { await electronAPI.applyUpdate(); } catch {}
        } else if (res === 'autoUpdater') {
        }
      }
    } catch (e) { console.warn('update failed', e); }
  };

  // لإتاحة المعاينة في المتصفح أثناء التطوير
  const shouldRender = isElectron;
  if (!shouldRender) return null;

  const [isWindowed, setIsWindowed] = React.useState(false);
  const handleWindowToggle = async () => {
    try {
      if (!electronAPI) return;
      if (isWindowed) {
        if (typeof (electronAPI as any).windowFullscreen === 'function') {
          await (electronAPI as any).windowFullscreen();
        }
        setIsWindowed(false);
      } else {
        if (typeof (electronAPI as any).windowWindowed === 'function') {
          await (electronAPI as any).windowWindowed();
        }
        setIsWindowed(true);
      }
    } catch (e) { console.warn('window toggle failed', e); }
  };

  return (
    <div
      className="fixed top-2 right-2 z-[9999] flex flex-col items-center gap-2"
      style={{ pointerEvents: 'auto' }}
    >
      

      <button
        type="button"
        aria-label="إغلاق"
        title="إغلاق"
        onClick={handleClose}
        className="inline-flex items-center justify-center w-9 h-9 rounded-md bg-transparent text-red-600 hover:bg-red-500/10 focus:outline-none dark:text-red-400 dark:hover:bg-red-400/10"
      >
        <X className="w-5 h-5" />
      </button>
      <button
        type="button"
        aria-label="تحديث"
        title="تحديث الصفحة"
        onClick={handleRefresh}
        className="inline-flex items-center justify-center w-9 h-9 rounded-md bg-transparent text-blue-600 hover:bg-blue-500/10 focus:outline-none dark:text-blue-400 dark:hover:bg-blue-400/10"
      >
        <RefreshCcw className={`w-5 h-5 ${isRefreshing ? 'animate-spin' : ''}`} />
      </button>
      <button
        type="button"
        aria-label="تصغير"
        title="تصغير"
        onClick={handleMinimize}
        className="inline-flex items-center justify-center w-9 h-9 rounded-md bg-transparent text-gray-800 hover:bg-black/10 focus:outline-none dark:text-white/80 dark:hover:bg-white/10"
      >
        <Minus className="w-5 h-5" />
      </button>
      <button
        type="button"
        aria-label="تكبير/استعادة"
        title={isWindowed ? "تكبير" : "استعادة الحجم"}
        onClick={handleWindowToggle}
        className="inline-flex items-center justify-center w-9 h-9 rounded-md bg-transparent text-gray-700 hover:bg-black/10 focus:outline-none dark:text-white/80 dark:hover:bg-white/10"
      >
        <Square className="w-5 h-5" />
      </button>
    </div>
  );
};

export default TitleBarOverlay;
