import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { doc, updateDoc } from "firebase/firestore";
import { db } from "@/firebase";
import { useFirebaseAuth } from "@/contexts/FirebaseAuthContext";

interface BranchRequestDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function BranchRequestDialog({ open, onOpenChange, onSuccess }: BranchRequestDialogProps) {
  const { user, userSubscription } = useFirebaseAuth();
  const [requestedLimit, setRequestedLimit] = useState("1");
  const [selectedPackage, setSelectedPackage] = useState("basic");
  const [requestLoading, setRequestLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  const handleRequestBranchPackage = async () => {
      if (!user) return;
      setRequestLoading(true);
      setMessage(null);
      try {
          const currentLimit = userSubscription?.branchPackage?.limit || 0;
          await updateDoc(doc(db, "users", user.uid), {
              branchPackage: {
                  status: 'pending',
                  requested: true,
                  limit: currentLimit + parseInt(requestedLimit),
                  packageType: selectedPackage,
                  requestedAt: new Date().toISOString()
              }
          });
          setMessage("تم إرسال طلب زيادة الفروع بنجاح بانتظار الموافقة.");
          
          // Dispatch event to force FirebaseAuthContext to refresh subscription status immediately
          window.dispatchEvent(new CustomEvent('userSubscriptionUpdated', {
            detail: {
              userId: user.uid,
              isActive: true
            }
          }));
          
          setTimeout(() => {
              onOpenChange(false);
              if (onSuccess) onSuccess();
          }, 1500);
      } catch (e: any) {
          setMessage("فشل إرسال الطلب: " + e.message);
      } finally {
          setRequestLoading(false);
      }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>تفعيل الفروع</DialogTitle>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="grid gap-2">
              <Label>عدد الفروع الإضافية المطلوب</Label>
              <Input 
                type="number" 
                min="1" 
                value={requestedLimit} 
                onChange={(e) => setRequestedLimit(e.target.value)}
                placeholder="أدخل عدد الفروع الإضافية"
              />
            </div>
            <div className="grid gap-2">
              <Label>نوع الباقة</Label>
              <select 
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                value={selectedPackage}
                onChange={(e) => setSelectedPackage(e.target.value)}
              >
                <option value="basic">باقة أساسية (شهرية)</option>
                <option value="quarterly">باقة ربع سنوية (3 شهور)</option>
                <option value="pro">باقة متقدمة (سنوية)</option>
                <option value="enterprise">باقة شركات (مدى الحياة)</option>
              </select>
            </div>
            {message && (
                <p className={`text-sm ${message.includes('نجاح') ? 'text-green-600' : 'text-red-600'}`}>
                    {message}
                </p>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => onOpenChange(false)}>إلغاء</Button>
            <Button 
              onClick={handleRequestBranchPackage} 
              disabled={requestLoading}
              className="bg-black text-white hover:bg-gray-800 dark:bg-white dark:text-black dark:hover:bg-gray-200"
            >
              {requestLoading ? "جاري الإرسال..." : "إرسال الطلب"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
  );
}
