import React, { useState, useCallback } from 'react';

const LogoLoader: React.FC<{ className?: string }> = ({ className = '' }) => {
  const isFile = typeof window !== 'undefined' && window.location && window.location.protocol === 'file:';
  const base = isFile ? './' : `${(import.meta as any)?.env?.BASE_URL || '/'}`;
  const [src, setSrc] = useState<string>(`${base}logo.svg`);
  const [attempt, setAttempt] = useState<number>(0);

  const handleError = useCallback(() => {
    setAttempt((prev) => {
      const next = prev + 1;
      if (next === 1) setSrc(`${base}logo.png`);
      else if (next === 2) setSrc(`${base}placeholder.svg`);
      return next;
    });
  }, []);

  return (
    <div className={`min-h-screen bg-background flex items-center justify-center ${className}`}>
      <style>{`
        @keyframes loaderSpin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
      <div className="flex flex-col items-center justify-center">
        <img
          src={src}
          onError={handleError}
          alt="logo"
          className="w-32 h-32"
          style={{ filter: 'drop-shadow(0 6px 12px rgba(0,0,0,0.15))', animation: 'loaderSpin 0.7s linear infinite', willChange: 'transform' }}
        />
        <p
          className="mt-5 text-2xl font-extrabold tracking-wide text-transparent bg-clip-text"
          style={{ fontFamily: `'Cairo','Tajawal','Noto Sans Arabic',sans-serif`, backgroundImage: 'var(--gradient-hero)' }}
        >
          صلى على النبي
        </p>
      </div>
    </div>
  );
};

export default LogoLoader;
