import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App.tsx'
import { ShiftProvider } from '@/contexts/ShiftContext'
import { FirebaseAuthProvider } from '@/contexts/FirebaseAuthContext'
import { ShopProvider } from '@/hooks/useShop'
import { initMobileSmsBridge } from '@/utils/mobileTransactionHandler'
import { ThemeProvider, useTheme } from 'next-themes'
import React, { useEffect } from 'react'
import { auth } from './firebase'
import { userDataService } from '@/integrations/firebase/services'
import { GlobalErrorBoundary } from '@/components/GlobalErrorBoundary'

// تم إزالة اختبار Firebase لتجنب أخطاء المصادقة

// تحديد النظام لإضافة كلاس إلى <html> لاستخدام قواعد CSS خاصة
try {
  const ua = navigator.userAgent || navigator.vendor || "";
  const isIOS = /iPad|iPhone|iPod/.test(ua);
  const el = document.documentElement;
  if (el) {
    el.classList.toggle('ios', isIOS);
    el.classList.toggle('android', !isIOS);
  }
} catch {}

try { initMobileSmsBridge(); } catch {}

try {
  (window as any).useState = (React as any).useState;
  (window as any).useEffect = (React as any).useEffect;
  (window as any).useRef = (React as any).useRef;
  (window as any).createContext = (React as any).createContext;
} catch {}

const ThemeBridge: React.FC = () => {
  const { theme = 'system' } = useTheme();
  useEffect(() => {
    try {
      const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
      const resolved = theme === 'system' ? (prefersDark ? 'dark' : 'light') : theme;
      document.documentElement.setAttribute('data-theme', resolved || 'light');
      document.documentElement.classList.toggle('dark', resolved === 'dark');
    } catch {}
  }, [theme]);
  return null;
};

createRoot(document.getElementById("root")!).render(
  <GlobalErrorBoundary>
    <ThemeProvider attribute="class" defaultTheme="system" enableSystem storageKey="theme">
      <FirebaseAuthProvider>
        <ShiftProvider>
          <ShopProvider>
            <App />
            <ThemeBridge />
          </ShopProvider>
        </ShiftProvider>
      </FirebaseAuthProvider>
    </ThemeProvider>
  </GlobalErrorBoundary>
);

