import React, { useEffect, useState } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import { Toaster } from "@/components/ui/sonner";
import { auth } from '@/firebase';
import { LogOut } from 'lucide-react';
import { Button } from '@/components/ui/button';

const SMSPortalLayout: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((u) => {
      setUser(u);
    });
    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    try {
      await auth.signOut();
      navigate('/sms-portal/login');
    } catch (error) {
      console.error('Logout error', error);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 font-cairo" dir="rtl">
      <div className="max-w-md mx-auto min-h-screen shadow-lg bg-white dark:bg-slate-950 border-x border-slate-200 dark:border-slate-800">
        <header className="p-4 border-b bg-primary text-primary-foreground flex justify-between items-center sticky top-0 z-10">
          <div>
             <h1 className="font-bold text-lg">بوابة الرسائل</h1>
             <div className="text-[10px] opacity-80 font-mono">SMS Portal v1.0</div>
          </div>
          
          {user && (
            <Button 
              variant="ghost" 
              size="sm" 
              onClick={handleLogout}
              className="text-primary-foreground hover:bg-primary-foreground/10 hover:text-white"
            >
              <LogOut className="h-4 w-4 ml-2" />
              خروج
            </Button>
          )}
        </header>
        
        <main className="p-4">
          <Outlet />
        </main>
      </div>
      <Toaster position="top-center" />
    </div>
  );
};

export default SMSPortalLayout;
