import { createContext, useContext, useState, useEffect } from 'react';
import { useFirebaseAuth } from '@/contexts/FirebaseAuthContext';

interface ShopContextType {
  shopId: string | null;
  shopName: string | null;
  loading: boolean;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

export function ShopProvider({ children }: { children: React.ReactNode }) {
  const { profile, user, loading: authLoading } = useFirebaseAuth();
  const [shopId, setShopId] = useState<string | null>(null);
  const [shopName, setShopName] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!authLoading && profile) {
      const overrideKey = profile?.userId ? `selectedShopId_${profile.userId}` : (user?.uid ? `selectedShopId_${user?.uid}` : 'selectedShopId');
      let selected = null as string | null;
      try { selected = localStorage.getItem(overrideKey) || null; } catch { }
      setShopId(selected || profile.shopId);
      // جلب اسم المحل الفعلي من بروفايل المستخدم عند إنشاء الحساب
      // مع بدائل آمنة عند عدم توفره
      setShopName(
        (profile as any)?.shopName ||
        user?.displayName ||
        'المحل'
      );
      setLoading(false);
    } else if (!authLoading) {
      setLoading(false);
    }
  }, [profile, authLoading]);

  useEffect(() => {
    const handler = () => {
      const overrideKey = profile?.userId ? `selectedShopId_${profile.userId}` : (user?.uid ? `selectedShopId_${user?.uid}` : 'selectedShopId');
      try {
        const selected = localStorage.getItem(overrideKey);
        setShopId(selected || (profile?.shopId ?? null));
      } catch { }
    };
    window.addEventListener('selectedShopIdChanged', handler);
    const storageListener = (e: StorageEvent) => {
      const overrideKey = profile?.userId ? `selectedShopId_${profile.userId}` : (user?.uid ? `selectedShopId_${user?.uid}` : 'selectedShopId');
      if (!e.key || e.key !== overrideKey) return;
      try {
        const selected = localStorage.getItem(overrideKey);
        setShopId(selected || (profile?.shopId ?? null));
      } catch { }
    };
    window.addEventListener('storage', storageListener);
    return () => {
      window.removeEventListener('selectedShopIdChanged', handler);
      window.removeEventListener('storage', storageListener);
    };
  }, [profile?.userId, user?.uid, profile?.shopId]);

  const value = {
    shopId,
    shopName,
    loading,
  };

  return (
    <ShopContext.Provider value={value}>
      {children}
    </ShopContext.Provider>
  );
}

export function useShop() {
  const context = useContext(ShopContext);
  if (context === undefined) {
    // إذا لم يتم استخدام السياق داخل ShopProvider، نعيد قيمة افتراضية
    return {
      shopId: null,
      shopName: null,
      loading: false
    };
  }
  return context;
}