import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

export type FontSize = 'small' | 'medium' | 'large';

interface FontSizeContextType {
  fontSize: FontSize;
  setFontSize: (size: FontSize) => void;
  isMobile: boolean;
  isDesktopApp: boolean;
}

const FontSizeContext = createContext<FontSizeContextType | undefined>(undefined);

interface FontSizeProviderProps {
  children: ReactNode;
}

export const FontSizeProvider: React.FC<FontSizeProviderProps> = ({ children }) => {
  const [fontSize, setFontSizeState] = useState<FontSize>(() => {
    // Try to get from localStorage first
    if (typeof window !== 'undefined') {
      const keys = ['appFontSize', 'desktopFontSize', 'mobileFontSize'];
      for (const key of keys) {
        const saved = localStorage.getItem(key) as FontSize | null;
        if (saved && ['small', 'medium', 'large'].includes(saved)) {
          return saved;
        }
      }
      // Default based on screen width (mobile: small, desktop: medium)
      return window.innerWidth <= 768 ? 'small' : 'medium';
    }
    return 'medium';
  });
  const [isMobile, setIsMobile] = useState(false);
  const [isDesktopApp, setIsDesktopApp] = useState(false);

  // Check if device is mobile
  useEffect(() => {
    const checkMobile = () => {
      const isMobileDevice = window.innerWidth <= 768;
      setIsMobile(isMobileDevice);
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);

    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Detect Electron/desktop app environment
  useEffect(() => {
    try {
      const isElectron = Boolean((window as any).electronAPI) ||
        (typeof navigator !== 'undefined' && navigator.userAgent.toLowerCase().includes('electron')) ||
        (typeof window !== 'undefined' && window.location && window.location.protocol === 'file:');
      setIsDesktopApp(isElectron);
    } catch {
      setIsDesktopApp(false);
    }
  }, []);

  // Load font size from localStorage on mount (support legacy and unified keys)
  // This is now handled in useState initialization, but kept for updates if needed
  useEffect(() => {
    // We can remove the initial load logic here since it's done in useState lazy init
    // to avoid flickering.
  }, []);

  // Apply font size to document root (desktop app and mobile)
  useEffect(() => {
    const root = document.documentElement;
    // Remove existing font size classes
    root.classList.remove('font-size-small', 'font-size-medium', 'font-size-large');
    // Add current font size class
    root.classList.add(`font-size-${fontSize}`);
  }, [fontSize]);

  const setFontSize = (size: FontSize) => {
    setFontSizeState(size);
    // Use unified key and keep desktop-specific key for Electron
    localStorage.setItem('appFontSize', size);
    if (isDesktopApp) {
      localStorage.setItem('desktopFontSize', size);
    }
  };

  return (
    <FontSizeContext.Provider value={{ fontSize, setFontSize, isMobile, isDesktopApp }}>
      {children}
    </FontSizeContext.Provider>
  );
};

export const useFontSize = () => {
  const context = useContext(FontSizeContext);
  if (context === undefined) {
    throw new Error('useFontSize must be used within a FontSizeProvider');
  }
  return context;
};